/**
 * Page-side scripts used by both browser surfaces.
 *
 * Everything here returns plain JSON so results survive CDP serialisation. The
 * selectors are built from tags and `:nth-of-type` rather than class names:
 * class names are generated by build tools and change between deploys, which
 * would make a saved assertion break for no reason.
 *
 * **Targets, not just selectors.** A positional selector is unusable on a page
 * built from component-library wrappers: a Naive UI form puts every label and
 * its input inside a wrapper that is not a sibling of anything the snapshot can
 * express, and `:nth-of-type` chains that long break as soon as one conditional
 * field appears. A person does not read those paths either — they look at the
 * label. So every action accepts a semantic target (label / text / role) and
 * resolves it in the page, falling back to a CSS selector when one is given.
 */

export interface ElementTarget {
  selector?: string;
  /** Text of the visible label next to a form field ("用户名"). */
  label?: string;
  /** Text of a button, link or other interactive element ("创建租户"). */
  text?: string;
  /** ARIA role, used to disambiguate ("button", "combobox"). */
  role?: string;
  /** Require an exact match instead of a prefix / substring match. */
  exact?: boolean;
}

/** Shorthand: a bare string is a CSS selector. */
export type TargetInput = string | ElementTarget;

export interface DomSnapshotNode {
  role: string;
  name: string;
  tag: string;
  selector: string;
  /**
   * Text of the label a person would read next to this control. Filled for form
   * fields even when the control has no accessible name of its own (a component
   * library's selection box shows the chosen value, not its field label).
   */
  field?: string;
  bounds: { x: number; y: number; width: number; height: number };
}

export interface DomSnapshot {
  url: string;
  title: string;
  viewport: { width: number; height: number };
  nodes: DomSnapshotNode[];
  /** Total visible elements considered before the cap was applied. */
  total: number;
  truncated: boolean;
}

export interface ElementPoint {
  ok: boolean;
  reason?: string;
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  tag?: string;
  text?: string;
  /** Selector of the element that was actually resolved. */
  selector?: string;
  matchedBy?: string;
}

export interface VisibilityProbe {
  exists: boolean;
  visible: boolean;
  reason?: string;
  bounds?: { x: number; y: number; width: number; height: number };
  selector?: string;
  name?: string;
}

export type WaitCondition = "visible" | "hidden" | "text" | "url" | "value";

export interface WaitResult {
  ok: boolean;
  waitedMs: number;
  timedOut?: boolean;
  reason?: string;
  /** What was matched, for the caller's log. */
  matched?: string;
}

/**
 * Shared helpers injected into every script: visibility, accessible name, a
 * stable selector path, and the semantic target resolver. Kept as a string so
 * it can be embedded in each expression without a build step.
 */
const HELPERS = `
  const isVisible = (el) => {
    if (!el || el.nodeType !== 1) return false;
    const style = getComputedStyle(el);
    if (style.visibility === "hidden" || style.display === "none") return false;
    if (Number(style.opacity) === 0) return false;
    if (el.hasAttribute("hidden") || el.getAttribute("aria-hidden") === "true") return false;
    const rect = el.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return false;
    // A fully transparent parent (common in "visibility toggles") still counts as
    // invisible: checkVisibility covers the ancestors in one call where supported.
    if (typeof el.checkVisibility === "function") {
      try {
        if (!el.checkVisibility({ checkOpacity: true, checkVisibilityCSS: true })) return false;
      } catch {}
    }
    return true;
  };
  const textOf = (el) => {
    const raw = (el.innerText || el.textContent || "").replace(/\\s+/g, " ").trim();
    return raw;
  };
  const labelOf = (el) => {
    const aria = el.getAttribute("aria-label");
    if (aria && aria.trim()) return aria.trim();
    const labelledBy = el.getAttribute("aria-labelledby");
    if (labelledBy) {
      const parts = [];
      for (const id of labelledBy.split(/\\s+/)) {
        const node = document.getElementById(id);
        if (node) parts.push(textOf(node));
      }
      const joined = parts.join(" ").trim();
      if (joined) return joined;
    }
    if (el.labels && el.labels.length) {
      const joined = Array.from(el.labels).map(textOf).join(" ").trim();
      if (joined) return joined;
    }
    return "";
  };
  const nameOf = (el) => {
    const label = labelOf(el);
    if (label) return label;
    const tag = el.tagName.toLowerCase();
    if (tag === "input" || tag === "textarea" || tag === "select") {
      return (
        el.getAttribute("placeholder") ||
        el.getAttribute("title") ||
        el.getAttribute("name") ||
        el.getAttribute("type") ||
        tag
      ).trim();
    }
    if (tag === "img") return (el.getAttribute("alt") || "").trim();
    return textOf(el);
  };
  const roleOf = (el) => {
    const explicit = (el.getAttribute("role") || "").trim();
    if (explicit) return explicit;
    const tag = el.tagName.toLowerCase();
    if (tag === "a") return el.hasAttribute("href") ? "link" : "text";
    if (tag === "button") return "button";
    if (tag === "select") return "combobox";
    if (tag === "textarea") return "textbox";
    if (tag === "input") {
      const type = (el.getAttribute("type") || "text").toLowerCase();
      if (type === "checkbox" || type === "radio") return type;
      if (type === "submit" || type === "button" || type === "reset") return "button";
      return "textbox";
    }
    if (/^h[1-6]$/.test(tag)) return "heading";
    if (tag === "li") return "listitem";
    if (tag === "table") return "table";
    if (tag === "tr") return "row";
    if (tag === "td" || tag === "th") return "cell";
    return "text";
  };
  const INTERACTIVE = 'a[href],button,input,select,textarea,summary,[role],[onclick],[tabindex]:not([tabindex="-1"])';
  const CONTROLS = 'input:not([type=hidden]),textarea,select,[contenteditable="true"],[role=textbox],[role=combobox],[role=searchbox]';
  const LABELISH = 'label,legend,dt,th,[role=columnheader],[class*="label"],[class*="Label"],[class*="title"],[class*="Title"]';
  const norm = (value) => String(value || "").replace(/\\s+/g, " ").trim().toLowerCase();
  const scoreName = (candidate, wanted, exact) => {
    const a = norm(candidate);
    const b = norm(wanted);
    if (!a || !b) return 0;
    if (a === b) return 100;
    if (exact) return 0;
    if (a.startsWith(b)) return 70;
    if (a.includes(b)) return 40;
    return 0;
  };
  const scriptPath = (el) => {
    if (el.id) {
      try {
        if (document.querySelectorAll("#" + CSS.escape(el.id)).length === 1) {
          return "#" + CSS.escape(el.id);
        }
      } catch {}
    }
    // Attributes an application sets on purpose survive a re-render; generated
    // class names do not. Try those before falling back to a positional path.
    for (const attr of ["data-testid", "data-test", "data-cy"]) {
      const value = el.getAttribute(attr);
      if (value) {
        const selector = el.tagName.toLowerCase() + "[" + attr + '="' + CSS.escape(value) + '"]';
        try {
          if (document.querySelectorAll(selector).length === 1) return selector;
        } catch {}
      }
    }
    const name = el.getAttribute("name");
    if (name) {
      const selector = el.tagName.toLowerCase() + '[name="' + CSS.escape(name) + '"]';
      try {
        if (document.querySelectorAll(selector).length === 1) return selector;
      } catch {}
    }
    const parts = [];
    let node = el;
    while (node && node.nodeType === 1 && node !== document.documentElement) {
      let part = node.tagName.toLowerCase();
      const parent = node.parentElement;
      if (parent) {
        const siblings = Array.from(parent.children).filter((child) => child.tagName === node.tagName);
        if (siblings.length > 1) part += ":nth-of-type(" + (siblings.indexOf(node) + 1) + ")";
      }
      parts.unshift(part);
      if (parts.length >= 7) break;
      node = parent;
    }
    return parts.join(" > ");
  };
  const rectOf = (el) => {
    const rect = el.getBoundingClientRect();
    return { x: Math.round(rect.x), y: Math.round(rect.y), width: Math.round(rect.width), height: Math.round(rect.height) };
  };
  /**
   * Resolves a label to the control it describes.
   *
   * Three shapes cover the libraries in use: <label for>, a control wrapped by
   * its <label>, and a wrapper that holds both the label and the control (Naive
   * UI, Ant Design, Element Plus). The last one climbs from the label until it
   * reaches a scope with exactly one visible control; a scope with many controls
   * only wins while its own text still mentions the label, so the form as a
   * whole never steals the match.
   */
  const controlForLabel = (wanted, exact) => {
    const anchors = Array.from(document.querySelectorAll(LABELISH)).filter(isVisible);
    const ranked = [];
    for (const el of anchors) {
      const score = scoreName(textOf(el), wanted, exact);
      if (score > 0) ranked.push({ el, score });
    }
    ranked.sort((a, b) => b.score - a.score);
    for (const item of ranked.slice(0, 6)) {
      const anchor = item.el;
      const own = anchor.control || anchor.querySelector(CONTROLS);
      if (own && isVisible(own)) return { el: own, matchedBy: "label" };
      let scope = anchor.parentElement;
      for (let depth = 0; scope && depth < 6; depth += 1, scope = scope.parentElement) {
        const controls = Array.from(scope.querySelectorAll(CONTROLS)).filter(isVisible);
        if (controls.length === 1) return { el: controls[0], matchedBy: "label" };
        if (controls.length > 1 && scoreName(textOf(scope), wanted, exact) > 0) {
          return { el: controls[0], matchedBy: "label" };
        }
      }
    }
    return null;
  };
  const resolveTarget = (target) => {
    if (typeof target === "string") target = { selector: target };
    if (!target) return { reason: "no-target" };
    if (target.selector) {
      let el = null;
      try { el = document.querySelector(target.selector); } catch { return { reason: "invalid-selector" }; }
      if (!el) return { reason: "not-found" };
      return { el, matchedBy: "selector" };
    }
    if (target.label) {
      const found = controlForLabel(target.label, target.exact === true);
      if (found) return found;
    }
    if (target.text || target.role) {
      const pool = Array.from(document.querySelectorAll(INTERACTIVE)).filter(isVisible);
      const ranked = [];
      for (const el of pool) {
        if (target.role && roleOf(el) !== target.role) continue;
        let score = 0;
        if (target.text) {
          score = Math.max(
            scoreName(nameOf(el), target.text, target.exact === true),
            scoreName(textOf(el), target.text, target.exact === true),
          );
        } else {
          score = 1;
        }
        if (score > 0) ranked.push({ el, score });
      }
      ranked.sort((a, b) => b.score - a.score);
      if (ranked.length) return { el: ranked[0].el, matchedBy: target.text ? "text" : "role" };
    }
    return { reason: "not-found" };
  };
  /**
   * Finds the smallest visible element whose text matches.
   *
   * The regular resolver only searches interactive elements, which is right for
   * clicking and typing but wrong for reading: the order number somebody wants
   * captured lives in a paragraph, not a control. Deepest-first keeps a short
   * order number from resolving to the whole page, which also contains it.
   */
  const textElement = (wanted, exact) => {
    const all = Array.from(document.body ? document.body.querySelectorAll("*") : []);
    let best = null;
    let bestScore = 0;
    for (const el of all) {
      if (!isVisible(el)) continue;
      const own = Array.from(el.childNodes)
        .filter((node) => node.nodeType === 3)
        .map((node) => node.textContent || "")
        .join(" ");
      const candidate = own.trim() ? own : el.children.length === 0 ? textOf(el) : "";
      if (!candidate) continue;
      const score = scoreName(candidate, wanted, exact);
      if (score === 0) continue;
      // Prefer a closer match, then the deeper element.
      const depth = (() => {
        let d = 0;
        let node = el;
        while (node && node.parentElement) {
          d += 1;
          node = node.parentElement;
        }
        return d;
      })();
      const weighted = score * 100 + depth;
      if (weighted > bestScore) {
        bestScore = weighted;
        best = el;
      }
    }
    return best;
  };
  /** The label a person reads next to this control, even without aria wiring. */
  const fieldLabelOf = (el) => {    const own = labelOf(el);
    if (own) return own;
    let scope = el.parentElement;
    for (let depth = 0; scope && depth < 5; depth += 1, scope = scope.parentElement) {
      const labels = Array.from(scope.querySelectorAll(LABELISH)).filter(isVisible);
      if (labels.length === 1) return textOf(labels[0]);
      if (labels.length > 1) return "";
    }
    return "";
  };
`;

/** Serialises a target into the page script without letting it inject code. */
function targetSource(target: TargetInput): string {
  return JSON.stringify(typeof target === "string" ? { selector: target } : target);
}

/** Human-readable name for an error message. */
export function describeTarget(target: TargetInput): string {
  if (typeof target === "string") return target;
  if (target.selector) return target.selector;
  if (target.label) return `标签「${target.label}」`;
  if (target.text) return `文本「${target.text}」`;
  if (target.role) return `role=${target.role}`;
  return "目标";
}

/**
 * Visible element inventory: interactive controls, headings and text blocks.
 *
 * Only what a user can see is reported, because the questions this answers are
 * "does this account see the delete button" and "what can this account do here".
 * Hidden markup is deliberately excluded — including it would make every account
 * look identical.
 */
export function buildDomSnapshotExpression(
  options: { maxNodes?: number; maxNameLength?: number } = {},
): string {
  const maxNodes = options.maxNodes ?? 400;
  const maxName = options.maxNameLength ?? 120;
  return `(() => {${HELPERS}
    const seen = new Set();
    const nodes = [];
    let total = 0;
    const all = Array.from(document.body ? document.body.querySelectorAll("*") : []);
    for (const el of all) {
      if (!isVisible(el)) continue;
      const role = roleOf(el);
      const interactive = el.matches(INTERACTIVE);
      const heading = /^h[1-6]$/.test(el.tagName.toLowerCase());
      const ownText = Array.from(el.childNodes)
        .filter((node) => node.nodeType === 3)
        .map((node) => node.textContent || "")
        .join(" ")
        .replace(/\\s+/g, " ")
        .trim();
      // Text containers with thousands of children produce noise; keep leaves and
      // elements that own text directly.
      const isTextLeaf = ownText.length > 0 && el.children.length <= 2;
      if (!interactive && !heading && !isTextLeaf) continue;
      const name = nameOf(el).slice(0, ${maxName});
      if (!name && !interactive) continue;
      const selector = scriptPath(el);
      if (seen.has(selector)) continue;
      seen.add(selector);
      total += 1;
      if (nodes.length >= ${maxNodes}) continue;
      const field = interactive ? fieldLabelOf(el).slice(0, ${maxName}) : "";
      nodes.push({
        role,
        name,
        tag: el.tagName.toLowerCase(),
        selector,
        ...(field && field !== name ? { field } : {}),
        bounds: rectOf(el),
      });
    }
    return {
      url: location.href,
      title: document.title,
      viewport: { width: innerWidth, height: innerHeight },
      nodes,
      total,
      truncated: total > nodes.length,
    };
  })()`;
}

/**
 * Resolves an element to viewport coordinates so the caller can click it with
 * real input events. A synthetic `el.click()` does not carry `isTrusted`, and
 * some frameworks ignore untrusted clicks.
 */
export function buildElementPointExpression(target: TargetInput): string {
  return `(() => {${HELPERS}
    const found = resolveTarget(${targetSource(target)});
    if (!found.el) return { ok: false, reason: found.reason };
    const el = found.el;
    if (!isVisible(el)) return { ok: false, reason: "not-visible" };
    el.scrollIntoView({ block: "center", inline: "center", behavior: "instant" });
    const rect = el.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return { ok: false, reason: "no-area" };
    return {
      ok: true,
      x: rect.x + rect.width / 2,
      y: rect.y + rect.height / 2,
      width: rect.width,
      height: rect.height,
      tag: el.tagName.toLowerCase(),
      text: nameOf(el).slice(0, 80),
      selector: scriptPath(el),
      matchedBy: found.matchedBy,
    };
  })()`;
}

/** Focuses a field so the caller can type into it with `Input.insertText`. */
export function buildFocusExpression(target: TargetInput): string {
  return `(() => {${HELPERS}
    const found = resolveTarget(${targetSource(target)});
    if (!found.el) return { ok: false, reason: found.reason };
    const el = found.el;
    if (!isVisible(el)) return { ok: false, reason: "not-visible" };
    if (typeof el.focus === "function") el.focus();
    if (el.disabled || el.readOnly) return { ok: false, reason: "disabled" };
    if (typeof el.select === "function" && typeof el.value === "string") el.select();
    const tag = el.tagName.toLowerCase();
    // The caller needs to know a field is a password before typing into it, so
    // the audit log can mask a value whose parameter name does not say "secret".
    const inputType = tag === "input" ? (el.getAttribute("type") || "text").toLowerCase() : undefined;
    return {
      ok: true,
      tag,
      selector: scriptPath(el),
      matchedBy: found.matchedBy,
      ...(inputType ? { inputType } : {}),
    };
  })()`;
}

/** Reports whether an element exists and is visible, for assertions. */
export function buildVisibilityExpression(target: TargetInput): string {
  return `(() => {${HELPERS}
    const found = resolveTarget(${targetSource(target)});
    if (!found.el) {
      return { exists: false, visible: false, reason: found.reason === "invalid-selector" ? "invalid-selector" : "not-found" };
    }
    const el = found.el;
    if (!isVisible(el)) {
      return {
        exists: true,
        visible: false,
        reason: "hidden",
        bounds: rectOf(el),
        selector: scriptPath(el),
        name: nameOf(el).slice(0, 80),
      };
    }
    return {
      exists: true,
      visible: true,
      bounds: rectOf(el),
      selector: scriptPath(el),
      name: nameOf(el).slice(0, 80),
    };
  })()`;
}

/**
 * Polls inside the page until a condition holds.
 *
 * This exists because the alternative costs a full MCP round trip per attempt:
 * a click that triggers an async render needs "sleep, read, sleep, read", and
 * every read is a request. One call that waits page-side turns a dozen round
 * trips into one, and it also removes the gap in which the page state drifts
 * between two calls (a menu closing on blur, an option appearing one frame late).
 */
export function buildWaitExpression(input: {
  condition: WaitCondition;
  target?: TargetInput;
  text?: string;
  timeoutMs: number;
  intervalMs?: number;
}): string {
  const interval = input.intervalMs ?? 150;
  const target = input.target === undefined ? "null" : targetSource(input.target);
  const text = JSON.stringify(input.text ?? "");
  return `(async () => {
    ${HELPERS}
    const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
    const wanted = ${text};
    const needle = norm(wanted);
    const target = ${target};
    const condition = ${JSON.stringify(input.condition)};
    const deadline = Date.now() + ${Math.max(100, Math.trunc(input.timeoutMs))};
    const started = Date.now();
    let lastReason = "not-yet";
    while (Date.now() < deadline) {
      if (condition === "text") {
        const body = document.body ? textOf(document.body) : "";
        if (!needle || norm(body).includes(needle)) return { ok: true, waitedMs: Date.now() - started };
        lastReason = "text-absent";
      } else if (condition === "url") {
        if (!needle || norm(location.href).includes(needle)) {
          return { ok: true, waitedMs: Date.now() - started, matched: location.href };
        }
        lastReason = "url-mismatch";
      } else {
        const found = resolveTarget(target);
        if (condition === "visible") {
          if (found.el && isVisible(found.el)) {
            return {
              ok: true,
              waitedMs: Date.now() - started,
              matched: found.matchedBy,
            };
          }
          lastReason = found.reason || "not-visible";
        } else if (condition === "hidden") {
          // "No longer there" is success: a toast disappears from the DOM as
          // often as it fades out.
          if (!found.el) return { ok: true, waitedMs: Date.now() - started };
          if (!isVisible(found.el)) return { ok: true, waitedMs: Date.now() - started };
          lastReason = "still-visible";
        } else if (condition === "value") {
          if (!found.el) {
            lastReason = found.reason || "not-found";
          } else {
            const value = String(found.el.value ?? found.el.textContent ?? "");
            if (norm(value).includes(needle)) {
              return { ok: true, waitedMs: Date.now() - started, matched: found.matchedBy };
            }
            lastReason = "value-mismatch";
          }
        } else {
          return { ok: false, waitedMs: 0, reason: "unknown-condition" };
        }
      }
      await wait(${interval});
    }
    return { ok: false, waitedMs: Date.now() - started, timedOut: true, reason: lastReason };
  })()`;
}

/**
 * Sets the value of a `<select>` (or a combobox that exposes one) by option
 * text, and reports what actually landed.
 *
 * Using the native setter plus `input`/`change` is what makes React, Vue and
 * Naive UI update: assigning `el.value` alone leaves their internal state stale,
 * so the visible box shows the new option while the form submits the old one.
 */
export function buildSelectExpression(target: TargetInput, option: string): string {
  return `(() => {${HELPERS}
    const found = resolveTarget(${targetSource(target)});
    if (!found.el) return { ok: false, reason: found.reason };
    let el = found.el;
    if (el.tagName.toLowerCase() !== "select") {
      el = el.querySelector ? el.querySelector("select") : null;
    }
    if (!el) return { ok: false, reason: "not-a-select" };
    const wanted = norm(${JSON.stringify(option)});
    const options = Array.from(el.options || []);
    const match =
      options.find((item) => norm(item.textContent) === wanted) ??
      options.find((item) => norm(item.textContent).includes(wanted)) ??
      options.find((item) => norm(item.value) === wanted);
    if (!match) {
      return {
        ok: false,
        reason: "option-not-found",
        available: options.slice(0, 20).map((item) => item.textContent.trim()),
      };
    }
    const view = el.ownerDocument.defaultView;
    const proto = view ? view.HTMLSelectElement.prototype : HTMLSelectElement.prototype;
    const descriptor = Object.getOwnPropertyDescriptor(proto, "value");
    if (descriptor && descriptor.set) descriptor.set.call(el, match.value);
    else el.value = match.value;
    el.dispatchEvent(new Event("input", { bubbles: true }));
    el.dispatchEvent(new Event("change", { bubbles: true }));
    return { ok: true, matchedBy: found.matchedBy, value: match.value, text: match.textContent.trim() };
  })()`;
}

/**
 * Reads a value out of the page for a flow's `read` step.
 *
 * It returns the text a person would see, not `outerHTML`: a flow substitutes
 * this into later steps (an order number, a generated account name), and markup
 * would poison the next field.
 */
export function buildReadExpression(target: TargetInput): string {
  return `(() => {${HELPERS}
    let found = resolveTarget(${targetSource(target)});
    if (!found.el) {
      // Reading is not limited to controls: capture an order number out of a
      // paragraph is the common case, and that element is not interactive.
      const spec = ${targetSource(target)};
      if (typeof spec === "object" && spec.text) {
        const el = textElement(spec.text, spec.exact === true);
        if (el) found = { el, matchedBy: "text" };
      }
    }
    if (!found.el) return { ok: false, reason: found.reason };
    const el = found.el;
    const tag = el.tagName.toLowerCase();
    const value =
      tag === "input" || tag === "textarea" || tag === "select"
        ? String(el.value ?? "")
        : textOf(el);
    return {
      ok: true,
      value: value.trim().slice(0, 500),
      matchedBy: found.matchedBy,
      selector: scriptPath(el),
    };
  })()`;
}

/** Scrolls a tab to the top; used to compare pages from a known position. */
export const RESET_SCROLL_EXPRESSION = "(() => { window.scrollTo(0, 0); return true; })()";

/** Waits for the document to reach a stable size, then reports it. */
export function buildStabilityExpression(): string {
  return `(async () => {
    const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
    let last = -1;
    let stable = 0;
    for (let round = 0; round < 30; round += 1) {
      const height = document.documentElement.scrollHeight;
      if (height === last) stable += 1;
      else { stable = 0; last = height; }
      if (stable >= 2) return { stable: true, height };
      await wait(120);
    }
    return { stable: false, height: last };
  })()`;
}
